 PulseView probeView;long probeFrames,probeTime;
 void assertQa(boolean ok,String message){if(!ok){android.util.Log.e("VultrIndicatorQA","FAIL: "+message);throw new IllegalStateException(message);}}
 void later(int step,long delay){new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(()->probeMotion(step),delay);}
 void mark(){probeFrames=probeView.frames;probeTime=android.os.SystemClock.uptimeMillis();}
 void probeMotion(int step){switch(step){
  case 0:for(PulseView v:indicators)if("indicator-preview-rack".equals(v.getTag()))probeView=v;assertQa(probeView!=null,"rack preview missing");assertQa(probeView.getWidth()==dp(80)&&probeView.getHeight()==dp(64),"preview slot changed");mark();later(1,650);break;
  case 1:long elapsed=android.os.SystemClock.uptimeMillis()-probeTime;long delta=probeView.frames-probeFrames;assertQa(delta>0&&delta<=elapsed/50+2,"visible frame budget "+delta);probeView.reducedForPreview(true);mark();later(2,200);break;
  case 2:assertQa(probeView.frames==probeFrames&&!probeView.shouldAnimate(),"reduced motion still animates");probeView.reducedForPreview(false);probeView.foreground(false);mark();later(3,200);break;
  case 3:assertQa(probeView.frames==probeFrames&&!probeView.posted,"background animation pending");probeView.foreground(true);probeView.setVisibility(android.view.View.INVISIBLE);mark();later(4,200);break;
  case 4:assertQa(probeView.frames==probeFrames,"hidden animation still advances");probeView.setVisibility(android.view.View.VISIBLE);probeView.state(true,true);mark();later(5,300);break;
  case 5:assertQa(probeView.frames>probeFrames,"visible animation did not resume");probeView.setTranslationX(10000);probeView.sync();mark();later(6,200);break;
  case 6:assertQa(probeView.frames==probeFrames,"offscreen animation still advances");probeView.setTranslationX(0);probeView.state(false,true);mark();later(7,200);break;
  case 7:assertQa(probeView.frames==probeFrames&&!probeView.shouldAnimate(),"stopped server animates");probeView.state(true,false);mark();later(8,200);break;
  case 8:assertQa(probeView.frames==probeFrames&&probeView.running&&!probeView.shouldAnimate(),"motion off changed power state or animates");probeView.state("booting",true);mark();later(9,300);break;
  case 9:assertQa(probeView.frames>probeFrames&&probeView.starting&&probeView.booting&&!probeView.running,"boot state animation missing or falsely running");probeView.reducedForPreview(true);mark();later(10,200);break;
  case 10:assertQa(probeView.frames==probeFrames&&!probeView.shouldAnimate(),"boot ignores reduced motion");probeView.reducedForPreview(false);probeView.state("creating",true);mark();later(11,250);break;
  case 11:assertQa(probeView.frames>probeFrames&&probeView.starting&&!probeView.booting,"creating standby state missing");probeView.state("unknown",true);mark();later(12,200);break;
  case 12:assertQa(probeView.frames==probeFrames&&!probeView.starting&&!probeView.shouldAnimate(),"stale/error state still animates");android.util.Log.i("VultrIndicatorQA","PASS: 80x64 slot, <=20fps, lifecycle gates, static running, startup/creating, reduced startup and stale stop");break;
 }}

